'use strict';

// MODULES //

var abs = require( '@stdlib/math/base/special/abs' );
var sqrt = require( '@stdlib/math/base/special/sqrt' );
var dlamch = require( '@stdlib/lapack/base/dlamch' );
var dnrm2 = require( '@stdlib/blas/base/dnrm2' );
var dscal = require( '@stdlib/blas/base/dscal' );


// VARIABLES //

var SAFE_MIN = 0.0;
var SAFE_MIN_INITIALIZED = false;


// FUNCTIONS //

/**
* Initializes the safe minimum value.
*
* @private
*/
function initSafeMin() {
	if ( !SAFE_MIN_INITIALIZED ) {
		var eps = dlamch( 'E' ); // Machine epsilon
		var sfmin = dlamch( 'S' ); // Safe minimum
		SAFE_MIN = sfmin / eps;
		SAFE_MIN_INITIALIZED = true;
	}
}


// MAIN //

/**
* Generates a real elementary reflector `H` such that `H * [alpha; x] = [beta; 0]`.
*
* ## Notes
*
* -   The function modifies the input array `x` in-place.
* -   On exit, `x` contains the vector `v[1:N]` where `v[0] = 1`.
* -   The matrix `H` is represented as `H = I - tau * v * v^T`.
* -   If `N = 1`, then `tau = 0` and `H` is the identity matrix.
*
* @private
* @param {NonNegativeInteger} N - number of elements in vector `v`
* @param {number} alpha - scalar alpha
* @param {Float64Array} x - input vector
* @param {integer} strideX - stride length for `x`
* @param {NonNegativeInteger} offsetX - starting index for `x`
* @returns {number} tau - scalar factor of the elementary reflector
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
*
* var x = new Float64Array( [ 1.0, 2.0, 3.0 ] );
*
* var tau = dlarfg( 3, 4.0, x, 1, 0 );
* // tau => ~1.714...
*
* // x now contains v[1:N]
* // x => <Float64Array>[ ~-0.557..., ~-0.742..., ~-0.371... ]
*/
function dlarfg( N, alpha, x, strideX, offsetX ) {
	var xnorm;
	var beta;
	var rsafmn;
	var safmin;
	var knt;
	var i;

	// Initialize safe minimum
	initSafeMin();
	safmin = SAFE_MIN;

	if ( N <= 1 ) {
		return 0.0;
	}

	// Compute the norm of x
	xnorm = dnrm2.ndarray( N - 1, x, strideX, offsetX );

	if ( xnorm === 0.0 ) {
		// H = I
		return 0.0;
	}

	// General case
	beta = -1.0 * ( ( alpha >= 0.0 ) ? 1.0 : -1.0 ) * sqrt( ( alpha * alpha ) + ( xnorm * xnorm ) );

	// Prevent overflow/underflow
	rsafmn = 1.0 / safmin;
	knt = 0;
	if ( abs( beta ) < safmin ) {
		// xnorm, beta may be inaccurate; scale x and recompute them
		while ( abs( beta ) < safmin ) {
			knt++;
			dscal.ndarray( N - 1, rsafmn, x, strideX, offsetX );
			beta *= rsafmn;
			alpha *= rsafmn;
		}

		// Recompute xnorm
		xnorm = dnrm2.ndarray( N - 1, x, strideX, offsetX );
		beta = -1.0 * ( ( alpha >= 0.0 ) ? 1.0 : -1.0 ) * sqrt( ( alpha * alpha ) + ( xnorm * xnorm ) );
	}

	// Compute tau and v
	var tau = ( beta - alpha ) / beta;
	var scale = 1.0 / ( alpha - beta );
	dscal.ndarray( N - 1, scale, x, strideX, offsetX );

	// Undo scaling
	if ( knt > 0 ) {
		for ( i = 0; i < knt; i++ ) {
			beta *= safmin;
		}
	}

	return tau;
}


// EXPORTS //

module.exports = dlarfg;
